<script setup lang="ts">
import {computed,nextTick,onMounted,onBeforeUnmount,ref,watch} from 'vue'
import {Folder,FolderOpen,FolderPlus,Upload,Download,Search,Grid2X2,List,ChevronRight,ChevronLeft,ArrowUp,RefreshCw,Trash2,RotateCcw,FileText,File,Server,HardDrive,LogOut,X,Info,Pencil,MoveRight,Check,LoaderCircle,ArrowUpDown,ExternalLink,ShieldCheck,PauseCircle,MoreHorizontal,Copy,Scissors,ClipboardPaste} from 'lucide-vue-next'
import {useHost,ApiError} from '@minhanos/app-sdk'
import catalogs from '../locales/catalogs.json'
import {fileActions,type ActionID} from './actions'
import {createFilesClient,endpoint,bytes,type Entry,type User,type Root,type TrashItem} from './client'
const props=withDefaults(defineProps<{embedded?:boolean;apiBase?:string;active?:boolean}>(),{embedded:false,apiBase:'/api',active:true})
const {request,setCSRF,upload,downloadURL}=createFilesClient(props.apiBase)
const host=useHost()
const unregister=host.i18n.registerCatalog('files',catalogs)
onBeforeUnmount(unregister)
const t=(key:string,params?:Record<string,string|number>)=>{host.profile.value.locale;return host.i18n.t(key,params)}
const profileBusy=ref(false)
async function updateProfile(event:Event,field:'locale'|'theme'){profileBusy.value=true;try{await host.updateProfile(request,{[field]:(event.target as HTMLSelectElement).value})}catch(e){error.value=host.errorMessage(e)}finally{profileBusy.value=false}}
const appRoot=ref<HTMLElement|null>(null)
const selectedPaths=ref<string[]>([])
const selectedEntries=computed(()=>entries.value.filter(e=>selectedPaths.value.includes(e.path)))
const clipboard=ref<{root:string;mode:'copy'|'cut';entries:Entry[]}|null>(null)
const menu=ref<{x:number;y:number;blank:boolean}|null>(null)
const menuElement=ref<HTMLElement|null>(null)
let menuTrigger:HTMLElement|null=null
let selectionAnchor=''
const user=ref<User|null>(null),passwordChange=ref(false),ready=ref(false),loginBusy=ref(false),loginName=ref(''),loginPassword=ref(''),error=ref(''),notice=ref('')
const roots=ref<Root[]>([]),root=ref('personal'),path=ref(''),entries=ref<Entry[]>([]),trashItems=ref<TrashItem[]>([]),trash=ref(false),selected=ref<Entry|null>(null),selectedTrash=ref<TrashItem|null>(null),query=ref(''),loading=ref(false),view=ref(localStorage.getItem('drive.view')||'grid'),hidden=ref(false),details=ref(true)
const history=ref<string[]>([])
const action=ref<'mkdir'|'rename'|'move'|'trash'|'remove'|null>(null),actionName=ref(''),busy=ref(false)
const editor=ref<{entry:Entry;content:string;original:string;etag:string;root:string}|null>(null),editorBusy=ref(false)
const input=ref<HTMLInputElement|null>(null)
type Transfer={id:number;name:string;progress:number;status:string;error:string;root:string;path:string;file:File;xhr?:XMLHttpRequest}
const transfers=ref<Transfer[]>([]),showTransfers=ref(false)
let loadRevision=0
let disposed=false
const display=computed(()=>entries.value.filter(e=>(hidden.value||!e.name.startsWith('.'))&&e.name.toLocaleLowerCase('vi').includes(query.value.toLocaleLowerCase('vi'))))
const rootName=computed(()=>roots.value.find(r=>r.id===root.value)?.name||'Tệp của tôi')
const crumbs=computed(()=>path.value.split('/').filter(Boolean))
const selectedItem=computed(()=>trash.value?selectedTrash.value:selected.value)
const dirty=computed(()=>!!editor.value&&editor.value.content!==editor.value.original)
const modalOpen=computed(()=>!!action.value||!!editor.value)
let dialogFrame=0
const dialogBounds=ref({left:0,top:0,width:0,height:0})
function trackDialog(){if(!props.embedded||!modalOpen.value||!props.active||disposed)return;const rect=appRoot.value?.getBoundingClientRect();if(rect){const next={left:rect.left,top:rect.top,width:rect.width,height:rect.height};if(JSON.stringify(next)!==JSON.stringify(dialogBounds.value))dialogBounds.value=next}dialogFrame=requestAnimationFrame(trackDialog)}
let priorFocus:HTMLElement|null=null
watch([modalOpen,()=>props.active],async ([value,active])=>{cancelAnimationFrame(dialogFrame);if(!active)return;if(value)priorFocus=document.activeElement as HTMLElement|null;await nextTick();if(value)trackDialog();if(value)document.querySelector<HTMLElement>('[aria-modal="true"] input, [aria-modal="true"] textarea, [aria-modal="true"] button')?.focus();else if(priorFocus?.isConnected)priorFocus.focus()})
function modalKeyboard(e:KeyboardEvent){if(!appVisible())return;if(!modalOpen.value)return;if(e.key==='Escape'&&!busy.value&&!editorBusy.value){if(editor.value)closeEditor();else action.value=null}if(e.key==='Tab'){const nodes=[...document.querySelectorAll<HTMLElement>('[aria-modal="true"] button, [aria-modal="true"] input, [aria-modal="true"] textarea')].filter(el=>!el.hasAttribute('disabled')&&el.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(first&&(e.shiftKey?document.activeElement===first:document.activeElement===last)){e.preventDefault();(e.shiftKey?last:first)?.focus()}}}
const activeTransfers=computed(()=>transfers.value.filter(t=>t.status==='uploading'||t.status==='queued').length)
function notify(message:string){notice.value=message;setTimeout(()=>notice.value='',6000)}
async function init(){const session=await request<{user:User;csrfToken:string;passwordChangeRequired?:boolean}>('/session');user.value=session.user;setCSRF(session.csrfToken);await host.loadProfile(request);passwordChange.value=!!session.passwordChangeRequired;if(passwordChange.value)return;roots.value=(await request<{roots:Root[]}>('/roots')).roots;await load()}
async function login(){loginBusy.value=true;error.value='';try{const session=await request<{user:User;csrfToken:string;passwordChangeRequired?:boolean}>('/login',{method:'POST',body:JSON.stringify({username:loginName.value,password:loginPassword.value})});loginPassword.value='';user.value=session.user;setCSRF(session.csrfToken);await host.loadProfile(request);passwordChange.value=!!session.passwordChangeRequired;if(passwordChange.value)return;roots.value=(await request<{roots:Root[]}>('/roots')).roots;await load()}catch(e){error.value=message(e)}finally{loginBusy.value=false}}
async function logout(){if(activeTransfers.value&&!confirm('Đăng xuất sẽ hủy các lần tải lên đang chạy. Tiếp tục?'))return;if(dirty.value&&!confirm('Bỏ thay đổi văn bản chưa lưu và đăng xuất?'))return;try{await request('/logout',{method:'POST',body:'{}'});transfers.value.forEach(t=>t.xhr?.abort());transfers.value=[];editor.value=null;user.value=null;entries.value=[];selected.value=null;selectedTrash.value=null;root.value='personal';path.value='';trash.value=false;setCSRF('')}catch(e){error.value=message(e)}}
function message(e:unknown){return host.errorMessage(e)}
async function load(){if(disposed)return;const revision=++loadRevision;loading.value=true;error.value='';selected.value=null;selectedPaths.value=[];selectedTrash.value=null;try{if(trash.value){const result=await request<TrashItem[]>(endpoint('trash',root.value,''));if(revision===loadRevision)trashItems.value=result}else{const result=await request<{entries:Entry[]}>(endpoint('list',root.value,path.value));if(revision===loadRevision)entries.value=result.entries}}catch(e){if(revision===loadRevision){entries.value=[];trashItems.value=[];error.value=message(e)}}finally{if(revision===loadRevision)loading.value=false}}
function navigate(next:string){history.value.push(path.value);path.value=next;query.value='';void load()}
function switchRoot(id:string){root.value=id;path.value='';trash.value=false;history.value=[];query.value='';void load()}
function openTrash(){root.value='personal';path.value='';trash.value=true;query.value='';void load()}
function choose(entry:Entry,event?:MouseEvent){
 if(event?.shiftKey&&selectionAnchor){const a=display.value.findIndex(e=>e.path===selectionAnchor),b=display.value.findIndex(e=>e.path===entry.path);selectedPaths.value=display.value.slice(Math.max(0,Math.min(a,b)),Math.max(a,b)+1).map(e=>e.path)}
 else if(event?.ctrlKey||event?.metaKey){selectedPaths.value=selectedPaths.value.includes(entry.path)?selectedPaths.value.filter(p=>p!==entry.path):[...selectedPaths.value,entry.path]}
 else selectedPaths.value=[entry.path]
 selected.value=selectedPaths.value.includes(entry.path)?entry:selectedEntries.value[0]||null;selectionAnchor=entry.path
}
function open(entry:Entry){if(entry.kind==='folder')navigate(entry.path);else if(entry.kind==='file')void openText(entry);else notify('Bản đầu không mở symlink hoặc tệp đặc biệt.')}
function setView(value:string){view.value=value;localStorage.setItem('drive.view',value)}
function begin(value:NonNullable<typeof action.value>){if((value==='rename'||value==='move')&&selectedPaths.value.length!==1)return;if(value!=='mkdir'&&!selected.value)return;action.value=value;actionName.value=value==='rename'?selected.value!.name:value==='move'?selected.value!.path:''}
async function submitAction(){if(!action.value)return;busy.value=true;error.value='';try{if(action.value==='trash'||action.value==='remove'){const targets=selectedEntries.value.slice();const failures:string[]=[];for(const item of targets){try{await request(endpoint(action.value,root.value,item.path),{method:'POST',body:JSON.stringify(action.value==='remove'?{confirm:true}:{})})}catch(e){failures.push(item.name+': '+message(e))}}action.value=null;await load();if(failures.length)error.value=failures.join(' · ');else notify(`Đã xử lý ${targets.length} mục.`);return}const target=action.value==='mkdir'?path.value:selected.value!.path;await request(endpoint(action.value,root.value,target),{method:'POST',body:JSON.stringify(action.value==='move'?{destination:actionName.value}:{name:actionName.value})});action.value=null;notify('Đã hoàn thành thao tác.');await load()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function restore(){if(!selectedTrash.value)return;try{await request(endpoint('restore','personal',''),{method:'POST',body:JSON.stringify({id:selectedTrash.value.id})});notify('Đã khôi phục về vị trí ban đầu.');await load()}catch(e){error.value=message(e)}}
async function openText(entry:Entry){if(dirty.value&&!confirm('Bỏ văn bản chưa lưu để mở tệp khác?'))return;editorBusy.value=true;error.value='';const editorRoot=root.value;try{const result=await request<{content:string;etag:string}>(endpoint('text',editorRoot,entry.path));editor.value={entry,content:result.content,original:result.content,etag:result.etag,root:editorRoot}}catch(e){error.value=message(e)}finally{editorBusy.value=false}}
function closeEditor(){if(dirty.value&&!confirm('Bỏ các thay đổi chưa lưu?'))return;editor.value=null}
async function saveText(){if(!editor.value||editorBusy.value)return;const state=editor.value;if(state.root==='system'&&!confirm(`Ghi thay đổi vào /${state.entry.path}? Một bản sao lưu sẽ được tạo cạnh tệp.`))return;editorBusy.value=true;try{const result=await request<{backup:string}>(endpoint('save-text',state.root,state.entry.path),{method:'POST',body:JSON.stringify({content:state.content,etag:state.etag})});state.original=state.content;const fresh=await request<{etag:string}>(endpoint('text',state.root,state.entry.path));state.etag=fresh.etag;notify('Đã lưu. Bản sao: '+result.backup);await load()}catch(e){error.value=message(e)}finally{editorBusy.value=false}}
function download(){if(selected.value)location.href=downloadURL(root.value,selected.value.path)}
async function startTransfer(t:Transfer){if(disposed)return;t.status='uploading';t.error='';t.progress=0;try{const handle=upload(t.root,t.path,t.file,p=>t.progress=p);t.xhr=handle.xhr;await handle.done;t.status='done';t.xhr=undefined;if(root.value===t.root&&path.value===t.path&&!trash.value)await load()}catch(e){t.status='error';t.error=message(e);t.xhr=undefined}}
async function queue(files:FileList|File[]|null){if(!files||trash.value||disposed)return;const targetRoot=root.value,targetPath=path.value;showTransfers.value=true;const ids:number[]=[];for(const file of Array.from(files)){if(file.size>128*1024*1024){error.value=`${file.name}: vượt giới hạn 128 MB.`;continue}const id=Date.now()+Math.random();transfers.value.push({id,name:file.name,progress:0,status:'queued',error:'',root:targetRoot,path:targetPath,file});ids.push(id)}for(const id of ids){if(disposed||!user.value)break;const t=transfers.value.find(t=>t.id===id);if(t)await startTransfer(t)}if(input.value)input.value.value=''}
function drop(event:DragEvent){event.preventDefault();void queue(event.dataTransfer?.files||null)}
onMounted(async()=>{try{await init()}catch(e){if(!(e instanceof ApiError&&e.code==='AUTH_REQUIRED'))error.value=message(e)}finally{ready.value=true}})
function beforeUnload(e:BeforeUnloadEvent){if(activeTransfers.value||dirty.value){e.preventDefault();e.returnValue=''}}
function appVisible(){return props.active&&!!appRoot.value?.getClientRects().length}
function canClose(){return !(activeTransfers.value||dirty.value)||confirm('Ứng dụng có tải lên hoặc văn bản chưa lưu. Đóng sẽ hủy phần chưa hoàn tất. Tiếp tục?')}
defineExpose({canClose})
onMounted(()=>{globalThis.addEventListener('keydown',modalKeyboard);globalThis.addEventListener('keydown',fileKeyboard);globalThis.addEventListener('beforeunload',beforeUnload);globalThis.addEventListener('resize',dismissMenu);globalThis.addEventListener('scroll',scrollMenu,true)})
onBeforeUnmount(()=>{disposed=true;cancelAnimationFrame(dialogFrame);globalThis.removeEventListener('keydown',modalKeyboard);globalThis.removeEventListener('keydown',fileKeyboard);globalThis.removeEventListener('beforeunload',beforeUnload);globalThis.removeEventListener('resize',dismissMenu);globalThis.removeEventListener('scroll',scrollMenu,true);transfers.value.forEach(t=>t.xhr?.abort());menu.value=null})
watch([query,hidden],()=>{selected.value=null;selectedPaths.value=[];selectedTrash.value=null;dismissMenu()})
const menuActions=computed(()=>fileActions({kind:menu.value?.blank||(!selected.value&&!selectedTrash.value)?'empty':trash.value?'trash':selected.value?.kind==='folder'?'folder':selected.value?.kind==='file'?'file':'special',count:selectedEntries.value.length,system:root.value==='system',canPaste:!!clipboard.value&&clipboard.value.root===root.value,canCopy:selectedEntries.value.length>0&&selectedEntries.value.every(e=>e.kind==='file'&&e.size<=128*1024*1024)},t))
const actionIcons={open:FolderOpen,download:Download,copy:Copy,cut:Scissors,paste:ClipboardPaste,rename:Pencil,move:MoveRight,delete:Trash2,properties:Info,restore:RotateCcw,mkdir:FolderPlus,upload:Upload,refresh:RefreshCw,grid:Grid2X2,list:List,'select-all':Check}
function scrollMenu(e:Event){if(menuElement.value?.contains(e.target as Node))return;dismissMenu()}
watch(()=>props.active,active=>{if(!active)dismissMenu()})
function dismissMenu(){menu.value=null}
async function context(event:MouseEvent,entry?:Entry,item?:TrashItem){event.preventDefault();event.stopPropagation();if(modalOpen.value)return;if(entry&&!selectedPaths.value.includes(entry.path))choose(entry);if(item)selectedTrash.value=item;if(!entry&&!item){selected.value=null;selectedPaths.value=[];selectedTrash.value=null}menuTrigger=event.currentTarget as HTMLElement;menu.value={x:Math.max(8,event.clientX),y:Math.max(8,event.clientY),blank:!entry&&!item};await nextTick();if(menuElement.value&&menu.value){const rect=menuElement.value.getBoundingClientRect();menu.value.x=Math.max(8,Math.min(menu.value.x,innerWidth-rect.width-8));menu.value.y=Math.max(8,Math.min(menu.value.y,innerHeight-rect.height-8));await nextTick();menuElement.value.querySelector<HTMLElement>('button:not(:disabled)')?.focus()}}
function overflow(event:MouseEvent){const rect=(event.currentTarget as HTMLElement).getBoundingClientRect();void contextAt(rect.left,rect.bottom,event)}
function contextAt(x:number,y:number,event:MouseEvent){const proxy={preventDefault:()=>{},stopPropagation:()=>{},clientX:x,clientY:y,currentTarget:event.currentTarget} as MouseEvent;return context(proxy,selected.value||undefined,selectedTrash.value||undefined)}
async function dispatch(id:ActionID){if(busy.value)return;
 const fromMenu=!!menu.value;const wasBlank=menu.value?.blank;const entry=selected.value;dismissMenu()
 if(id==='mkdir'||id==='rename'||id==='move'){begin(id);return}
 if(id==='open'&&entry){open(entry);return}
 if(id==='download'){download();return}
 if(id==='properties'){details.value=true;return}
 if(id==='restore'){await restore();return}
 if(id==='delete'){begin(root.value==='system'?'remove':'trash');return}
 if(id==='upload'){input.value?.click();return}
 if(id==='refresh'){await load();return}
 if(id==='grid'||id==='list'){setView(id);return}
 if(id==='select-all'){selectedPaths.value=display.value.map(e=>e.path);selected.value=display.value[0]||null;return}
 if(id==='copy'||id==='cut'){const items=selectedEntries.value;if(!items.length)return;if(id==='copy'&&items.some(e=>e.kind!=='file'||e.size>128*1024*1024)){notify('Sao chép hiện hỗ trợ tệp thường tối đa 128 MB; chưa sao chép thư mục.');return}if(items.some(e=>e.kind==='special'||e.kind==='symlink'))return;clipboard.value={root:root.value,mode:id,entries:items.map(e=>({...e}))};notify(`${id==='copy'?'Đã sao chép':'Đã cắt'} ${items.length} mục vào bộ nhớ ứng dụng.`);return}
 if(id==='paste'){const clip=clipboard.value;if(!clip||clip.root!==root.value){notify('Chỉ dán trong cùng không gian lưu trữ.');return}if(clip.entries.length>100){notify('Giới hạn 100 mục mỗi lần dán.');return}busy.value=true;const destination=fromMenu&&!wasBlank&&entry?.kind==='folder'?entry.path:path.value;const destinationRoot=root.value;const failed:string[]=[];const remaining:Entry[]=[];for(const item of clip.entries){const target=[destination,item.name].filter(Boolean).join('/');if(target===item.path){failed.push(item.name+': nguồn và đích giống nhau');remaining.push(item);continue}try{await request(endpoint(clip.mode==='copy'?'copy':'move',destinationRoot,item.path),{method:'POST',body:JSON.stringify({destination:target})})}catch(e){failed.push(item.name+': '+message(e));remaining.push(item)}}if(clip.mode==='cut')clipboard.value=remaining.length?{...clip,entries:remaining}:null;busy.value=false;await load();if(failed.length)error.value=failed.join(' · ');else notify('Đã dán các mục.');return}
}
function fileKeyboard(e:KeyboardEvent){if(!appVisible())return;const target=e.target as HTMLElement;if(menu.value){if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const nodes=[...menuElement.value!.querySelectorAll<HTMLButtonElement>('button:not(:disabled)')];const current=nodes.indexOf(document.activeElement as HTMLButtonElement);nodes[e.key==='Home'?0:e.key==='End'?nodes.length-1:(current+(e.key==='ArrowDown'?1:-1)+nodes.length)%nodes.length]?.focus()}if(e.key==='Escape'){e.preventDefault();dismissMenu();menuTrigger?.focus()}if(e.key==='Tab')dismissMenu();return}if(modalOpen.value||!appRoot.value?.contains(target)||target.closest('input,textarea,[contenteditable="true"]'))return;let id:ActionID|undefined;if(e.key==='F2')id='rename';if(e.key==='Delete'&&!trash.value)id='delete';if(e.ctrlKey||e.metaKey){id=({c:'copy',x:'cut',v:'paste',a:'select-all'} as Record<string,ActionID>)[e.key.toLowerCase()]}if((e.shiftKey&&e.key==='F10')||e.key==='ContextMenu'){e.preventDefault();const rect=target.getBoundingClientRect();void contextAt(rect.left,rect.bottom,{currentTarget:target} as unknown as MouseEvent);return}if(id){e.preventDefault();void dispatch(id)}}

</script>

<template>
 <div ref="appRoot" class="files-app" :class="{embedded:props.embedded}">
 <div v-if="user&&!host.canOpenSettings()" class="files-profile-controls" :inert="modalOpen"><label>{{t('files.settings.language')}} <select :value="host.profile.value.locale" :disabled="profileBusy" @change="updateProfile($event,'locale')"><option value="vi-VN">Tiếng Việt</option><option value="en-US">English</option></select></label><label>{{t('files.settings.theme')}} <select :value="host.profile.value.theme" :disabled="profileBusy" @change="updateProfile($event,'theme')"><option value="light">{{t('files.settings.light')}}</option><option value="dark">{{t('files.settings.dark')}}</option><option value="system">{{t('files.settings.system')}}</option></select></label></div>
  <header v-if="!props.embedded" class="drive-top" :inert="modalOpen"><a href="/" class="drive-brand"><span><FolderOpen :size="21"/></span><strong>MinhAnOS <b>Drive</b></strong></a><span class="drive-preview">File Station · Preview 0.1</span><div v-if="user" class="drive-account"><span class="avatar">{{user.displayName.charAt(0)}}</span><span>{{user.displayName}}</span><button aria-label="Đăng xuất" @click="logout"><LogOut :size="17"/></button></div></header>
  <main v-if="!ready" class="login-wrap"><LoaderCircle class="spinning"/> Đang mở Drive…</main>
  <main v-else-if="user&&passwordChange" class="login-wrap"><section class="drive-login" role="alert"><span class="login-folder"><FolderOpen :size="36"/></span><h1>{{t('files.passwordChange.title')}}</h1><p>{{t('files.passwordChange.hint')}}</p><a class="primary" href="/accounts/">{{t('files.passwordChange.open')}}</a></section></main>
  <main v-else-if="!user" class="login-wrap"><section class="drive-login"><span class="login-folder"><FolderOpen :size="36"/></span><div class="eyebrow">KHÔNG GIAN CỦA BẠN</div><h1>Tệp của bạn.<br>Luôn trong tầm tay.</h1><p>Đăng nhập Drive bằng tài khoản MinhAnOS.<br>Ứng dụng hoạt động độc lập với desktop.</p><p v-if="props.embedded">Phiên desktop không còn hợp lệ. Đăng nhập lại desktop để tiếp tục.</p><form v-else @submit.prevent="login"><label>Tên đăng nhập<input v-model="loginName" autocomplete="username" required maxlength="64" autofocus></label><label>Mật khẩu<input v-model="loginPassword" type="password" autocomplete="current-password" required maxlength="256"></label><p v-if="error" role="alert" class="error">{{error}}</p><button class="primary" :disabled="loginBusy">{{loginBusy?'Đang đăng nhập…':'Mở không gian của tôi'}}<ChevronRight :size="17"/></button></form><small><ShieldCheck :size="14"/> Phiên Drive riêng · Tệp tách theo tài khoản</small></section></main>
  <div v-else class="drive-layout" :inert="modalOpen">
   <aside class="drive-sidebar"><span class="nav-label">KHÔNG GIAN LƯU TRỮ</span><button v-for="item in roots" :key="item.id" :class="{active:root===item.id&&!trash}" @click="switchRoot(item.id)"><component :is="item.id==='system'?Server:Folder" :size="19"/>{{item.name}}<span v-if="item.id==='system'" class="admin-label">ADMIN</span></button><button :class="{active:trash}" @click="openTrash"><Trash2 :size="19"/>Thùng rác</button><div class="files-sidebar-bottom"><HardDrive :size="19"/><strong>Drive độc lập</strong><p>Dữ liệu nằm trên máy chủ.<br>Desktop là lối truy cập tùy chọn.</p><span>Giới hạn tải lên: 128 MB/tệp</span></div></aside>
   <main class="drive-main" @dragover.prevent @drop="drop">
    <div class="drive-heading"><div><span class="eyebrow">{{root==='system'?'QUẢN TRỊ MÁY CHỦ':'KHÔNG GIAN CÁ NHÂN'}}</span><h1>{{trash?'Thùng rác':crumbs.at(-1)||rootName}}</h1><p>{{trash?'Khôi phục tệp về vị trí cũ.':root==='system'?'Tệp thật trên Debian · Thao tác bằng quyền quản trị.':'Một nơi cho tài liệu và những điều bạn đang tạo ra.'}}</p></div><div v-if="!trash" class="heading-actions"><button @click="dispatch('mkdir')"><FolderPlus :size="17"/>{{t('files.actions.mkdir')}}</button><button class="primary" @click="input?.click()"><Upload :size="17"/>{{t('files.actions.upload')}}</button><input ref="input" type="file" multiple hidden @change="queue(($event.target as HTMLInputElement).files)"></div></div>
    <div class="drive-toolbar"><div class="navigation-actions"><button :disabled="!history.length||trash" aria-label="Quay lại" @click="path=history.pop()||'';load()"><ChevronLeft :size="18"/></button><button :disabled="!path||trash" aria-label="Thư mục cha" @click="navigate(crumbs.slice(0,-1).join('/'))"><ArrowUp :size="17"/></button><button :aria-label="t('files.actions.refresh')" :disabled="loading" @click="load"><RefreshCw :size="17" :class="{spinning:loading}"/></button></div><label class="file-search"><Search :size="17"/><input v-model="query" placeholder="Tìm trong thư mục…" aria-label="Tìm trong thư mục"></label><label class="hidden-toggle"><input v-model="hidden" type="checkbox">Tệp ẩn</label><div class="view-toggle"><button aria-label="Thao tác tệp" @click="overflow"><MoreHorizontal :size="19"/></button><button :class="{chosen:view==='grid'}" :aria-label="t('files.actions.grid')" @click="setView('grid')"><Grid2X2 :size="18"/></button><button :class="{chosen:view==='list'}" :aria-label="t('files.actions.list')" @click="setView('list')"><List :size="18"/></button><button aria-label="Ẩn hiện thông tin" @click="details=!details"><Info :size="18"/></button></div></div>
    <div v-if="selectedPaths.length||clipboard" class="selection-bar"><span>{{t('files.selection.count',{count:selectedPaths.length})}}</span><button :disabled="busy||!selectedEntries.length||selectedEntries.some(e=>e.kind!=='file'||e.size>128*1024*1024)" @click="dispatch('copy')"><Copy :size="15"/>{{t('files.actions.copy')}}</button><button :disabled="!selectedPaths.length" @click="dispatch('cut')"><Scissors :size="15"/>{{t('files.actions.cut')}}</button><button :disabled="!clipboard||clipboard.root!==root" @click="dispatch('paste')"><ClipboardPaste :size="15"/>{{t('files.actions.paste')}}</button><button :disabled="!selectedPaths.length" @click="dispatch('delete')"><Trash2 :size="15"/>{{root==='system'?'Xóa vĩnh viễn':'Thùng rác'}}</button></div><div class="breadcrumbs"><button @click="trash?openTrash():navigate('')"><component :is="trash?Trash2:root==='system'?Server:Folder" :size="15"/>{{trash?'Thùng rác':rootName}}</button><template v-for="(part,index) in crumbs" :key="index"><ChevronRight :size="12"/><button @click="navigate(crumbs.slice(0,index+1).join('/'))">{{part}}</button></template><span v-if="root==='system'" class="system-path">/{{path}}</span></div>
    <div v-if="error" class="error-banner" role="alert"><Info :size="17"/><span>{{error}}</span><button aria-label="Đóng lỗi" @click="error='' "><X :size="16"/></button></div><div v-if="notice" class="notice" role="status"><Check :size="16"/>{{notice}}</div>
    <div class="files-layout" :class="{'without-details':!details}"><section class="file-browser" aria-label="Danh sách tệp" @contextmenu="context($event)">
     <div v-if="loading" class="empty-files"><LoaderCircle class="spinning" :size="28"/><p>Đang đọc thư mục…</p></div>
     <template v-else-if="trash"><div v-if="!trashItems.length" class="empty-files"><Trash2 :size="40"/><h2>Thùng rác đang trống</h2></div><button v-for="item in trashItems.filter(t=>t.name.toLocaleLowerCase('vi').includes(query.toLocaleLowerCase('vi')))" :key="item.id" class="trash-row" @contextmenu.stop="context($event,undefined,item)" :class="{selected:selectedTrash?.id===item.id}" @click="selectedTrash=item"><File :size="23"/><span><strong>{{item.name}}</strong><small>{{item.path}}</small></span><time>{{new Date(item.deleted).toLocaleDateString('vi')}}</time></button></template>
     <template v-else><div class="browser-label"><span>{{display.length}} MỤC</span><span>{{view==='grid'?'Chạm để chọn · Mở để duyệt':'Tên · Kích thước · Quyền'}}</span></div><div v-if="!display.length" class="empty-files"><FolderOpen :size="47"/><h2>{{error?'Chưa đọc được thư mục':query?'Không tìm thấy tệp':'Không gian đang trống'}}</h2><p v-if="!error">{{query?'Thử tìm bằng tên khác.':'Tạo thư mục hoặc kéo tệp vào đây để bắt đầu.'}}</p></div><div class="file-items" :class="{rows:view==='list'}"><div v-for="entry in display" :key="entry.path" class="file-cell"><button class="file-item" @contextmenu.stop="context($event,entry)" :class="{selected:selectedPaths.includes(entry.path),cut:clipboard?.mode==='cut'&&clipboard.root===root&&clipboard.entries.some(e=>e.path===entry.path),folder:entry.kind==='folder'}" :aria-label="`Chọn ${entry.name}`" @click="choose(entry,$event)" @dblclick="open(entry)" @keydown.enter.prevent="open(entry)"><span class="file-symbol"><component :is="entry.kind==='folder'?Folder:entry.kind==='file'?FileText:Info" :size="45" :stroke-width="1.3"/></span><span class="file-name">{{entry.name}}</span><span class="file-size">{{entry.kind==='folder'?'Thư mục':bytes(entry.size)}}</span><span class="file-mode">{{entry.mode}}</span><span class="file-date">{{new Date(entry.modified).toLocaleDateString('vi')}}</span></button><button class="file-more" :aria-label="`Thao tác ${entry.name}`" @click.stop="choose(entry);overflow($event)"><MoreHorizontal :size="18"/></button></div></div></template>
    </section>
    <aside v-if="details" class="file-inspector" aria-label="Thông tin tệp"><div class="inspector-label">Thông tin <Info :size="15"/></div><template v-if="selectedItem"><div class="inspector-preview"><component :is="!trash&&selected?.kind==='folder'?Folder:FileText" :size="54" :stroke-width="1.2"/></div><h2>{{selectedItem.name}}</h2><p class="inspector-path">{{selectedItem.path}}</p><template v-if="!trash&&selected"><dl><div><dt>Loại</dt><dd>{{selected.kind}}</dd></div><div><dt>Kích thước</dt><dd>{{bytes(selected.size)}}</dd></div><div><dt>Quyền Linux</dt><dd>{{selected.mode}}</dd></div><div><dt>UID / GID</dt><dd>{{selected.uid}} / {{selected.gid}}</dd></div><div><dt>Thay đổi</dt><dd>{{new Date(selected.modified).toLocaleString('vi')}}</dd></div></dl><div class="inspector-actions"><button v-if="selected.kind==='folder'" class="primary" @click="open(selected)"><FolderOpen :size="17"/>{{t('files.actions.openFolder')}}</button><template v-if="selected.kind==='file'"><button class="primary" @click="dispatch('download')"><Download :size="16"/>Tải xuống</button><button :disabled="editorBusy" @click="openText(selected)"><FileText :size="16"/>Xem / sửa văn bản</button></template><template v-if="selected.kind==='file'||selected.kind==='folder'"><button :disabled="selectedPaths.length!==1||busy" @click="dispatch('rename')"><Pencil :size="16"/>{{t('files.actions.rename')}}</button><button :disabled="selectedPaths.length!==1||busy" @click="dispatch('move')"><MoveRight :size="16"/>Di chuyển</button><button class="danger-text" @click="dispatch('delete')"><Trash2 :size="16"/>{{root==='system'?'Xóa khỏi hệ thống':'Đưa vào thùng rác'}}</button></template></div></template><button v-else class="primary" @click="dispatch('restore')"><RotateCcw :size="16"/>{{t('files.actions.restore')}}</button></template><div v-else class="inspector-placeholder"><Folder :size="35"/><p>Chọn một tệp hoặc thư mục<br>để xem thông tin và thao tác.</p></div></aside></div>
    <footer class="files-footer"><span>{{root==='system'?'Agent Debian · Không mở tệp thiết bị, filesystem ảo hoặc symlink':'Tệp riêng theo tài khoản · Lưu trữ trên máy chủ'}}</span><button @click="showTransfers=!showTransfers"><ArrowUpDown :size="16"/>Tác vụ <span v-if="activeTransfers">{{activeTransfers}}</span></button></footer>
   </main>
  </div>
  <section v-if="user&&showTransfers&&props.active" :inert="modalOpen" class="transfer-panel" aria-label="Tác vụ tải lên"><header><strong>Tác vụ tải lên</strong><button aria-label="Thu gọn tác vụ" @click="showTransfers=false"><X :size="17"/></button></header><p v-if="!transfers.length" class="muted">Chưa có tác vụ. Tệp tối đa 128 MB.</p><div v-for="t in transfers" :key="t.id" class="transfer-row"><File :size="22"/><div><strong>{{t.name}}</strong><small>{{t.status==='done'?'Đã tải lên':t.status==='error'?t.error:t.status==='queued'?'Đang chờ':`${t.progress}% · ${t.progress===100?'Đang chờ máy chủ xác nhận':'Đang gửi'}`}}</small><div class="progress"><i :style="{width:t.progress+'%'}"></i></div></div><button v-if="t.status==='uploading'" :aria-label="`Hủy ${t.name}`" @click="t.xhr?.abort()"><X :size="17"/></button><button v-if="t.status==='error'" :aria-label="`Thử lại ${t.name}`" @click="startTransfer(t)"><RotateCcw :size="17"/></button><Check v-if="t.status==='done'" :size="17"/></div><p class="transfer-note">Đổi thư mục không hủy upload. Đóng hoặc tải lại trang sẽ ngắt truyền; bản đầu chưa hỗ trợ resume.</p></section>
  <Teleport to="body"><div v-if="(action||editor)&&props.active" class="files-app fs-dialog-portal" :style="props.embedded?{left:dialogBounds.left+'px',top:dialogBounds.top+'px',width:dialogBounds.width+'px',height:dialogBounds.height+'px',right:'auto',bottom:'auto'}:{}"><div v-if="action" class="modal-scrim"><form class="action-dialog" role="dialog" aria-modal="true" :aria-label="{mkdir:'Thư mục mới',rename:'Đổi tên',move:'Di chuyển',trash:'Đưa vào thùng rác',remove:'Xóa tệp hệ thống'}[action]" @submit.prevent="submitAction"><h2>{{{mkdir:'Thư mục mới',rename:'Đổi tên',move:'Di chuyển',trash:'Đưa vào thùng rác?',remove:'Xóa khỏi hệ thống?'}[action]}}</h2><p v-if="action==='trash'||action==='remove'">{{selectedPaths.length>1?`${selectedPaths.length} mục đã chọn`:selected?.path}}<br>{{action==='remove'?'Xóa vĩnh viễn tệp hoặc thư mục rỗng trên Debian.':'Bạn có thể khôi phục từ Thùng rác.'}}</p><label v-else>{{action==='move'?'Đường dẫn đích đầy đủ trong không gian hiện tại':'Tên'}}<input v-model="actionName" required maxlength="4096" autofocus></label><p v-if="error" class="error" role="alert">{{error}}</p><footer><button type="button" :disabled="busy" @click="action=null">Hủy</button><button class="primary" :disabled="busy">{{busy?'Đang thực hiện…':'Xác nhận'}}</button></footer></form></div>
  <div v-if="editor" class="modal-scrim"><section class="text-editor" role="dialog" aria-modal="true" aria-label="Trình sửa văn bản"><header><div><FileText :size="20"/><span><strong>{{editor.entry.name}}</strong><small>{{editor.root==='system'?'Hệ thống Debian':'Tệp của tôi'}} / {{editor.entry.path}}</small></span><i v-if="dirty" class="draft-dot"></i></div><button aria-label="Đóng trình sửa" :disabled="editorBusy" @click="closeEditor"><X :size="19"/></button></header><div v-if="error" class="error-banner" role="alert">{{error}}</div><textarea v-model="editor.content" aria-label="Nội dung tệp" spellcheck="false" :disabled="editorBusy"></textarea><footer><span>UTF-8 · Tối đa 256 KB · Tạo bản sao trước khi lưu</span><button class="primary" :disabled="!dirty||editorBusy" @click="saveText">{{editorBusy?'Đang lưu…':'Lưu thay đổi'}}</button></footer></section></div>
 </div></Teleport><Teleport to="body"><div v-if="menu" class="files-app fs-menu-portal"><div class="menu-dismiss" @pointerdown="dismissMenu"></div><nav ref="menuElement" class="files-context-menu" role="menu" aria-label="Thao tác tệp" :style="{left:menu.x+'px',top:menu.y+'px'}" @contextmenu.prevent><button v-for="item in menuActions" :key="item.id" role="menuitem" :disabled="item.disabled||busy" :class="{divider:item.divider,danger:item.danger}" @click="dispatch(item.id)"><component :is="actionIcons[item.id]" :size="16"/><span>{{item.label}}</span><kbd v-if="item.shortcut">{{item.shortcut}}</kbd></button></nav></div></Teleport>
 </div>
</template>
